mutation SetStartCommand($id: String!, $command: String!, $confirm: String) {
  setStartCommand(id: $id, command: $command, confirm: $confirm) {
    id
    startCommand
    command
    phase
    __typename
  }
}

mutation DeleteService($id: String!, $confirm: String) {
  deleteService(id: $id, confirm: $confirm)
}
